package com.farika.soundflow;
import android.app.Application;import android.content.*;import android.content.res.AssetFileDescriptor;import android.database.*;import android.net.Uri;import android.provider.OpenableColumns;import java.io.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowContentResolver;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalProbe168Test {
 static class Provider extends ContentProvider {int mode=0;public boolean onCreate(){return true;}public String getType(Uri uri){return "audio/mpeg";}public Cursor query(Uri u,String[] projection,String selection,String[] args,String order){if(mode==3)throw new SecurityException();if(mode==4)throw new IllegalStateException();if(mode==2)return null;MatrixCursor c=new MatrixCursor(new String[]{OpenableColumns.DISPLAY_NAME});if(mode!=1)c.addRow(new Object[]{"a.mp3"});return c;}public AssetFileDescriptor openAssetFile(Uri uri,String mode)throws FileNotFoundException{if(this.mode==5){try{File file=new File(getContext().getCacheDir(),"synthetic-audio.bin");try(FileOutputStream out=new FileOutputStream(file)){out.write(new byte[]{1,2,3});}return new AssetFileDescriptor(android.os.ParcelFileDescriptor.open(file,android.os.ParcelFileDescriptor.MODE_READ_ONLY),0,3);}catch(IOException e){throw new FileNotFoundException();}}throw new FileNotFoundException("Synthetic provider");}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] args){return 0;}public int update(Uri u,ContentValues v,String s,String[] args){return 0;}}
 Context c;Provider provider;LocalAudioStore.Entry e;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();provider=new Provider();android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority="synthetic.audio;com.android.externalstorage.documents";info.exported=true;provider.attachInfo(c,info);ShadowContentResolver.registerProviderInternal("synthetic.audio",provider);e=new LocalAudioStore.Entry();e.document="content://synthetic.audio/a";}
 @Test public void readableProviderDescriptorIsAvailable(){provider.mode=5;assertEquals(LocalAudioStore.Access.AVAILABLE,new LocalAudioStore(c).probe(e));}
 @Test public void emptyProviderCursorConfirmsMissing(){provider.mode=1;assertEquals(LocalAudioStore.Access.MISSING,new LocalAudioStore(c).probe(e));}
 @Test public void unknownProviderFileNotFoundDoesNotProveDeletion(){assertEquals(LocalAudioStore.Access.UNAVAILABLE,new LocalAudioStore(c).probe(e));}
 @Test public void nullProviderCursorKeepsReference(){provider.mode=2;assertEquals(LocalAudioStore.Access.UNAVAILABLE,new LocalAudioStore(c).probe(e));}
 @Test public void revokedAccessIsNotDeletion(){provider.mode=3;assertEquals(LocalAudioStore.Access.NO_PERMISSION,new LocalAudioStore(c).probe(e));}
 @Test public void providerFailureIsNotDeletion(){provider.mode=4;assertEquals(LocalAudioStore.Access.UNAVAILABLE,new LocalAudioStore(c).probe(e));}
 @Test public void mountedLocalMissingCanBePruned(){assertEquals(LocalAudioStore.Access.MISSING,new LocalAudioStore(c){protected boolean localStorageReady(Uri uri){return true;}}.probe(e));}
 @Test public void unavailableExternalVolumeIsNotDeletion(){ShadowContentResolver.registerProviderInternal("com.android.externalstorage.documents",provider);provider.mode=1;e.document="content://com.android.externalstorage.documents/document/0123:a.mp3";assertEquals(LocalAudioStore.Access.UNAVAILABLE,new LocalAudioStore(c){protected boolean localStorageReady(Uri u){return false;}}.probe(e));}
}
